mapper.select:
SELECT p.id, p.name, p.category_id, p.price, p.stock, p.description, p.main_image, p.images, p.status, p.sales, p.create_time, p.update_time FROM product p WHERE p.status = #{status} AND ( MATCH(p.name) AGAINST(CONCAT('+', #{escapedKeyword}) IN BOOLEAN MODE) OR p.name LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '\\'
OR levenshtein(LOWER(p.name), LOWER(#{fuzzyKeyword})) <= 2
) ORDER BY MATCH(p.name) AGAINST(CONCAT('+', #{escapedKeyword}) IN BOOLEAN MODE) DESC, p.name LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '\\' DESC, p.sales DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM product p WHERE p.status = #{status} AND ( MATCH(p.name) AGAINST(CONCAT('+', #{escapedKeyword}) IN BOOLEAN MODE) OR p.name LIKE CONCAT('%', #{likeKeyword}, '%') ESCAPE '\\'
OR levenshtein(LOWER(p.name), LOWER(#{fuzzyKeyword})) <= 2
)
